import { test, expect } from '@playwright/test';

test.describe('Unread Notification Visual Distinction', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should visually distinguish unread notifications from read ones', async ({ page }) => {
    // Verify notification list is visible
    const notificationList = page.getByRole('region', { name: /notifications/i });
    await expect(notificationList).toBeVisible();

    // Verify unread notification has distinct styling (e.g, a badge or different background)
    const unreadNotification = page.getByText('New message from John');
    await expect(unreadNotification).toBeVisible();
    await expect(unreadNotification).toHaveClass(/unread-badge/);

    // Verify read notification has standard styling
    const readNotification = page.getByText('System update');
    await expect(readNotification).toBeVisible();
    await expect(readNotification).not.toHaveClass(/unread-badge/);

    // Verify unread notification has a distinct background color
    const unreadBg = page.locator('[data-testid="unread-notification-bg"]');
    await expect(unreadBg).toHaveCSS('background-color', /rgba\(255, 100, 0, 0.1\)/);

    // Verify read notification has standard background color
    const readBg = page.locator('[data-testid="read-notification-bg"]');
    await expect(readBg).toHaveCSS('background-color', /rgba\(25, 111, 159, 0.1\)/);

    // Verify unread notification has a notification count badge
    const unreadBadge = page.locator('[data-testid="unread-count-badge"]');
    await expect(unreadBadge).toBeVisible();
    await expect(unreadBadge).toContainText('1');
  });

  test('should remove visual distinction when unread notification is marked as read', async ({ page }) => {
    // Verify unread notification is visible and styled distinctly
    const unreadNotification = page.getByText('Meeting reminder');
    await expect(unreadNotification).toBeVisible();
    await expect(unreadNotification).toHaveClass(/unread-badge/);

    // Click the mark as read button
    const markAsReadButton = page.getByRole('button', { name: /mark as read/i });
    await markAsReadButton.click();

    // Wait for the notification to update
    await page.waitForTimeout(500);

    // Verify unread badge is removed
    await expect(unreadNotification).not.toHaveClass(/unread-badge/);

    // Verify background color reverts to standard read style
    const unreadBg = page.locator('[data-testid="unread-notification-bg"]');
    await expect(unreadBg).not.toHaveCSS('background-color', /rgba\(255, 100, 0, 0.1\)/);

    // Verify read notification styling is applied
    const readBg = page.locator('[data-testid="read-notification-bg"]');
    await expect(readBg).toHaveCSS('background-color', /rgba\(25, 119, 168, 0.1\)/);

    // Verify notification count badge is removed
    const unreadBadge = page.locator('[data-testid="unread-count-badge"]');
    await expect(unreadBadge).not.toBeVisible();
  });
});
